export async function loadDetails(
  route: Extract<DetailRoute, { kind: "member" | "funder" }>,
  signal: AbortSignal,
  fetch: typeof globalThis.fetch,
  origin: string,
): Promise<Exclude<DetailState, { kind: "loading" }>> {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, 10_000);
  try {
    const response = await fetch(
      `${origin}/${route.kind === "member" ? "members" : "funders"}/${route.id}`,
      { signal: controller.signal },
    );
    if (response.status === 404) return { kind: "not-found" };
    if (!response.ok)
      throw new Error(
        "The details service is unavailable. Try again in a moment.",
      );
    const body: unknown = await response.json();
    const state: DetailState =
      route.kind === "member"
        ? { kind: "member", details: readMember(body) }
        : { kind: "funder", details: readFunder(body) };
    if (
      (state.kind === "member"
        ? state.details.member.id
        : state.details.funder.id
      ).toLowerCase() !== route.id.toLowerCase()
    )
      return malformed();
    return state;
  } catch (error) {
    if (signal.aborted) throw error;
    return {
      kind: "error",
      message: timedOut
        ? "Details are taking too long. Try again."
        : error instanceof Error &&
            !(error instanceof TypeError || error instanceof SyntaxError)
          ? error.message
          : "Couldn’t connect to details. Check your connection and try again.",
    };
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", cancel);
  }
}
import {
  searchConfiguration,
  type Entity,
  type SearchMatchSource,
} from "../search";
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readEntities(body: unknown): Entity[] {
  if (!isRecord(body) || !Array.isArray(body.entities)) {
    throw new Error("Search returned an unexpected response. Try again.");
  }

  return body.entities.map((value: unknown) => {
    if (
      !isRecord(value) ||
      typeof value.name !== "string" ||
      typeof value.id !== "string" ||
      (value.kind !== "MP" && value.kind !== "Funder") ||
      (value.funder_kind !== null && typeof value.funder_kind !== "string")
    ) {
      throw new Error("Search returned an unexpected response. Try again.");
    }
    const source = value.match_source;
    if (!isRecord(source))
      throw new Error("Search returned an unexpected match source. Try again.");
    let matchSource: SearchMatchSource;
    switch (source.kind) {
      case "name":
        matchSource = { kind: "name" };
        break;
      case "alias":
        if (typeof source.name !== "string" || !source.name.trim())
          throw new Error(
            "Search returned an unexpected match source. Try again.",
          );
        matchSource = { kind: "alias", name: source.name };
        break;
      default:
        throw new Error(
          "Search returned an unexpected match source. Try again.",
        );
    }
    if (value.kind === "MP") {
      if (
        !/^[1-9]\d*$/u.test(value.id) ||
        Number(value.id) > 2147483647 ||
        value.funder_kind !== null ||
        matchSource.kind !== "name"
      )
        throw new Error(
          "Search returned an unexpected MP identity. Try again.",
        );
      return {
        id: value.id,
        name: value.name,
        kind: "MP",
        funderKind: null,
        matchSource,
      };
    }
    if (
      !/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu.test(
        value.id,
      )
    )
      throw new Error(
        "Search returned an unexpected funder identity. Try again.",
      );
    return {
      id: value.id,
      name: value.name,
      kind: "Funder",
      funderKind: value.funder_kind,
      matchSource,
    };
  });
}

export async function searchEntities(
  term: string,
  signal: AbortSignal,
  strictness: number,
  fetch: typeof globalThis.fetch,
  origin: string,
): Promise<Entity[]> {
  const controller = new AbortController();
  let timedOut = false;
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  const timeout = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, searchConfiguration.timeoutMs);

  try {
    const params = new URLSearchParams({
      term,
      max_entries: String(searchConfiguration.maxEntriesPerType),
      strictness: String(strictness),
    });
    const response = await fetch(`${origin}/search?${params}`, {
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(
        "The search service is unavailable. Try again in a moment.",
      );
    }
    const body: unknown = await response.json();
    return readEntities(body);
  } catch (error) {
    if (timedOut) throw new Error("Search is taking too long. Try again.");
    if (signal.aborted) throw error;
    if (error instanceof TypeError || error instanceof SyntaxError) {
      throw new Error(
        "Couldn’t connect to search. Check your connection and try again.",
      );
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    signal.removeEventListener("abort", cancel);
  }
}
#!/usr/bin/env bash
set -uo pipefail

"$@" &
server_pid=$!
node /app/frontend/build &
frontend_pid=$!

stop_children() {
    kill -TERM "$server_pid" "$frontend_pid" 2>/dev/null || true
    wait "$server_pid" 2>/dev/null || true
    wait "$frontend_pid" 2>/dev/null || true
}
trap 'stop_children; exit 0' TERM INT

wait -n "$server_pid" "$frontend_pid"
status=$?
stop_children
if [ "$status" -eq 0 ]; then
    status=1
fi
exit "$status"
FROM rust:1.98.1-bookworm@sha256:93ce27a88655056a51dbdd8f5f2d7ddc071c7b0070fb288a37b5a285fc83971e AS chef
RUN cargo install cargo-chef --version 0.1.78 --locked
WORKDIR /app

FROM chef AS planner
COPY Cargo.toml Cargo.lock ./
COPY exposed ./exposed
RUN cargo chef prepare --recipe-path recipe.json

FROM chef AS builder
ARG CARGO_BUILD_JOBS=2
COPY --from=planner /app/recipe.json recipe.json
RUN cargo chef cook --release --locked --recipe-path recipe.json
COPY Cargo.toml Cargo.lock ./
COPY exposed ./exposed
COPY .sqlx ./.sqlx
ENV SQLX_OFFLINE=true
RUN cargo build --release --locked --package exposed --bin exposed
RUN ldd target/release/exposed

FROM debian:bookworm-slim@sha256:7c7b2c966bc9ee8cedfeef67e0e279108992c77681fa595db4a9d65c06ccc587 AS runtime
RUN apt-get update \
    && apt-get install --no-install-recommends -y ca-certificates libgcc-s1 \
    && rm -rf /var/lib/apt/lists/*
WORKDIR /app
COPY --from=builder /app/target/release/exposed /usr/local/bin/exposed
USER 10001:10001

FROM node:24-bookworm-slim@sha256:a5f4366e834695d5f363b920c104953a535d3a9864d1bdf74566a0ebe01daee5 AS frontend-builder
WORKDIR /app/frontend
COPY frontend/package.json frontend/package-lock.json ./
RUN npm ci
COPY frontend/ ./
RUN npm run build && npm prune --omit=dev

FROM runtime AS frontend-server
USER root
RUN apt-get update \
    && apt-get install --no-install-recommends -y tini bash libstdc++6 \
    && rm -rf /var/lib/apt/lists/*
COPY --from=frontend-builder /usr/local/bin/node /usr/local/bin/node
COPY --chmod=755 docker/frontend-server.sh /usr/local/bin/frontend-server
COPY --from=frontend-builder /app/frontend/build /app/frontend/build
COPY --from=frontend-builder /app/frontend/package.json /app/frontend/package.json
COPY --from=frontend-builder /app/frontend/node_modules /app/frontend/node_modules
ENV PORT=8080 HOST=0.0.0.0 EXPOSED_API_ORIGIN=http://127.0.0.1:6999
USER 10001:10001
EXPOSE 8080
ENTRYPOINT ["/usr/bin/tini", "--", "/usr/local/bin/frontend-server"]
CMD ["exposed", "server"]

FROM runtime AS migrate
COPY db/migrations/ /app/db/migrations/
ENTRYPOINT ["exposed", "migrate"]
CMD ["run", "--source", "/app/db/migrations"]

FROM runtime AS data
ENTRYPOINT ["exposed", "data"]
CMD ["--help"]

FROM runtime AS binary
EXPOSE 6999
ENTRYPOINT ["exposed"]
CMD ["server"]
